// Claude's review tests for A20 (empty-panel help) and A21 (Log filters). agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, newProject, type Mock, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

function mock(id: string, urlPattern: string, status: number): Mock {
  return {
    id, name: id, enabled: true, method: 'ANY', urlPattern,
    response: { status, headers: { 'content-type': 'text/plain' }, body: id, bodyEncoding: 'text', delayMs: 0 },
    source: 'manual', createdAt: 0,
  };
}

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function open(enabled = true, mocks: Mock[] = []): Promise<{ page: Page; panel: Page }> {
  const p = newProject('p1', fixture.origin);
  p.scenarios[0]!.mocks.push(...mocks);
  const s = emptyState();
  await session.setState({ ...s, settings: { ...s.settings, enabled }, enabledOrigins: [fixture.origin], projects: [p] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

test.describe('A20: an empty panel says why', () => {
  test('on and nothing yet: say so, and Reload reloads the page', async () => {
    const { page, panel } = await open();
    try {
      await expect(panel.getByTestId('log-empty')).toContainText('No calls yet');
      await page.evaluate(() => ((window as unknown as { marker: number }).marker = 1));
      // Wait for the reload itself: reading the page mid-navigation throws.
      const reloaded = page.waitForEvent('load');
      await panel.getByTestId('log-empty-reload').click();
      await reloaded;
      expect(await page.evaluate(() => (window as unknown as { marker?: number }).marker ?? 0)).toBe(0);
      await page.evaluate(async () => (await fetch('/api/goals')).text());
      await expect(panel.getByTestId('log-row')).toHaveCount(1);
      await expect(panel.getByTestId('log-empty')).toHaveCount(0);
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('mocking off: say so, and Turn on turns it on', async () => {
    const { page, panel } = await open(false);
    try {
      await expect(panel.getByTestId('log-empty')).toContainText('Mocking is off');
      await panel.getByTestId('log-empty-turn-on').click();
      await expect.poll(async () => (await readState()).settings.enabled).toBe(true);
      await expect(panel.getByTestId('log-empty')).toContainText('No calls yet');
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('the Mocks tab with no mocks says how to make one', async () => {
    const { page, panel } = await open();
    try {
      await panel.getByTestId('tab-mocks').click();
      await expect(panel.getByTestId('mocks-empty')).toContainText('No mocks yet');
      await panel.getByTestId('mock-new').click();
      await expect(panel.getByTestId('mocks-empty')).toHaveCount(0);
    } finally {
      await panel.close();
      await page.close();
    }
  });
});

test.describe('A21: Log filters', () => {
  async function traffic(page: Page) {
    await page.evaluate(async () => {
      const t = async (u: string, init?: RequestInit) => (await fetch(u, init)).text();
      await t('/api/a');
      await t('/api/goals');
      await t('/api/echo', { method: 'POST', body: 'x' });
      await t('/api/missing');
      await t('/api/err');
      const ws = new WebSocket(`${location.origin.replace('http', 'ws')}/ws/real`);
      await new Promise((r) => (ws.onopen = r));
      await new Promise((r) => setTimeout(r, 150));
      ws.close();
    });
  }
  const paths = async (panel: Page) =>
    (await panel.getByTestId('log-row').locator('.log-col-path').allTextContents()).map((s) => s.trim());

  test('type, method and status chips: OR inside a group, AND between groups', async () => {
    const { page, panel } = await open(true, [mock('a', '/api/a', 200), mock('err', '/api/err', 500)]);
    try {
      await traffic(page);
      const rows = panel.getByTestId('log-row');
      await expect(rows.filter({ hasText: '/ws/real' }).first()).toBeVisible();
      const total = await rows.count();
      expect(total).toBeGreaterThanOrEqual(7);

      await panel.getByTestId('log-chip-type-MOCK').click();
      await expect(panel.getByTestId('log-chip-type-MOCK')).toHaveAttribute('aria-pressed', 'true');
      expect(await paths(panel)).toEqual(['/api/a', '/api/err']);
      await expect(panel.getByTestId('log-filter-count')).toHaveText(`2 of ${total}`);

      await panel.getByTestId('log-chip-status-5xx').click();
      expect(await paths(panel)).toEqual(['/api/err']);

      await panel.getByTestId('log-chip-type-real').click();
      expect(await paths(panel)).toEqual(['/api/err']);
      await panel.getByTestId('log-chip-status-5xx').click();
      await panel.getByTestId('log-chip-status-4xx').click();
      expect(await paths(panel)).toEqual(['/api/missing']);

      await panel.getByTestId('log-filter-clear').click();
      await expect(rows).toHaveCount(total);
      await expect(panel.getByTestId('log-filter-count')).toHaveCount(0);
      await expect(panel.getByTestId('log-chip-type-MOCK')).toHaveAttribute('aria-pressed', 'false');
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('method chips list only the methods in the log; WS covers every socket row', async () => {
    const { page, panel } = await open(true, [mock('a', '/api/a', 200)]);
    try {
      await traffic(page);
      await expect(panel.getByTestId('log-row').filter({ hasText: '/ws/real' }).first()).toBeVisible();
      await expect(panel.getByTestId('log-chip-method-GET')).toBeVisible();
      await expect(panel.getByTestId('log-chip-method-POST')).toBeVisible();
      await expect(panel.getByTestId('log-chip-method-WS')).toBeVisible();
      await expect(panel.getByTestId('log-chip-method-PUT')).toHaveCount(0);
      await panel.getByTestId('log-chip-method-WS').click();
      const methods = (await panel.getByTestId('log-row').locator('.log-col-method').allTextContents()).map((s) => s.trim());
      expect(methods.length).toBeGreaterThanOrEqual(2);
      expect(methods.every((m) => m.startsWith('WS'))).toBe(true);
      await panel.getByTestId('log-chip-method-POST').click();
      expect(await paths(panel)).toContain('/api/echo');
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('chips and the URL filter combine, and Save as scenario saves only what shows', async () => {
    const { page, panel } = await open(true, [mock('a', '/api/a', 200), mock('err', '/api/err', 500)]);
    try {
      await traffic(page);
      await expect(panel.getByTestId('log-row').filter({ hasText: '/ws/real' }).first()).toBeVisible();
      await panel.getByTestId('log-chip-type-real').click();
      await panel.getByTestId('log-chip-method-GET').click();
      expect(await paths(panel)).toEqual(['/api/goals', '/api/missing']);
      await panel.getByTestId('log-filter').fill('goals');
      expect(await paths(panel)).toEqual(['/api/goals']);
      await panel.getByTestId('log-filter').fill('');

      await panel.getByTestId('save-scenario').click();
      await panel.getByTestId('save-scenario-name').fill('Real GETs');
      await panel.getByTestId('save-scenario-submit').click();
      await expect.poll(async () => (await readState()).projects[0]!.scenarios.find((s) => s.name === 'Real GETs')?.mocks.map((m) => m.urlPattern))
        .toEqual(['/api/goals', '/api/missing']);
    } finally {
      await panel.close();
      await page.close();
    }
  });
});
